ALTER TABLE public.appointments ADD COLUMN IF NOT EXISTS package_scheduling_key uuid;
CREATE UNIQUE INDEX appointments_package_request_start_idx ON public.appointments(account_id,package_scheduling_key,starts_at) WHERE package_scheduling_key IS NOT NULL;
CREATE OR REPLACE FUNCTION public.finance_query(_filters jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE aid uuid:=public.current_account_id(); page integer:=greatest(1,coalesce((_filters->>'page')::integer,1)); size integer:=least(100,greatest(1,coalesce((_filters->>'page_size')::integer,20))); result jsonb;
BEGIN
 IF NOT coalesce(public.can_manage_professional_finance(aid),false) THEN RAISE EXCEPTION 'Sem permissão financeira.'; END IF;
 WITH base AS (
 SELECT t.*,p.full_name AS patient_name,coalesce(x.paid,0) AS received_cents,greatest(t.amount_cents-coalesce(x.paid,0),0) AS balance_cents,CASE WHEN t.cancelled_at IS NOT NULL THEN 'cancelled' WHEN coalesce(x.paid,0)>=t.amount_cents THEN 'paid' WHEN coalesce(x.paid,0)>0 THEN 'partial' ELSE 'pending' END AS status
 FROM public.professional_receivables t JOIN public.patients p ON p.id=t.patient_id LEFT JOIN LATERAL(SELECT sum(r.amount_cents) AS paid FROM public.professional_receipts r WHERE r.receivable_id=t.id AND r.status='confirmed') x ON true
 WHERE t.account_id=aid AND (nullif(_filters->>'patient_id','') IS NULL OR t.patient_id=(_filters->>'patient_id')::uuid) AND (nullif(_filters->>'service_id','') IS NULL OR t.appointment_type_id=(_filters->>'service_id')::uuid) AND (nullif(_filters->>'package_id','') IS NULL OR t.package_id=(_filters->>'package_id')::uuid) AND (nullif(_filters->>'appointment_id','') IS NULL OR t.appointment_id=(_filters->>'appointment_id')::uuid OR t.package_id=(SELECT package_id FROM public.appointments WHERE id=(_filters->>'appointment_id')::uuid AND account_id=aid)) AND (nullif(_filters->>'modality','') IS NULL OR t.modality=_filters->>'modality') AND (coalesce(_filters->>'packages_only','false')<>'true' OR t.package_id IS NOT NULL)
 ), titles AS (
 SELECT * FROM base t WHERE (nullif(_filters->>'from','') IS NULL OR t.due_on>=(_filters->>'from')::date) AND (nullif(_filters->>'to','') IS NULL OR t.due_on<=(_filters->>'to')::date) AND (nullif(_filters->>'status','') IS NULL OR t.status=_filters->>'status') AND (coalesce(_filters->>'pending_only','false')<>'true' OR t.status IN ('pending','partial')) AND (nullif(_filters->>'method','') IS NULL OR EXISTS(SELECT 1 FROM public.professional_receipts r WHERE r.receivable_id=t.id AND r.method=_filters->>'method'))
 ), receipts AS (
 SELECT r.*,b.patient_id,b.patient_name,b.service_name_snapshot,b.package_id,b.appointment_id,b.modality FROM public.professional_receipts r JOIN base b ON b.id=r.receivable_id WHERE r.account_id=aid AND (nullif(_filters->>'from','') IS NULL OR r.received_on>=(_filters->>'from')::date) AND (nullif(_filters->>'to','') IS NULL OR r.received_on<=(_filters->>'to')::date) AND (nullif(_filters->>'method','') IS NULL OR r.method=_filters->>'method') AND (nullif(_filters->>'receipt_status','') IS NULL OR r.status=_filters->>'receipt_status')
 )
 SELECT jsonb_build_object('rows',CASE WHEN _filters->>'view'='receipts' THEN coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM (SELECT * FROM receipts ORDER BY received_on DESC,id LIMIT size OFFSET (page-1)*size) s),'[]'::jsonb) ELSE coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM (SELECT * FROM titles ORDER BY due_on DESC,id LIMIT size OFFSET (page-1)*size) s),'[]'::jsonb) END,'total',CASE WHEN _filters->>'view'='receipts' THEN (SELECT count(*) FROM receipts) ELSE (SELECT count(*) FROM titles) END,'summary',jsonb_build_object('received_cents',(SELECT coalesce(sum(amount_cents),0) FROM receipts WHERE status='confirmed'),'pending_cents',(SELECT coalesce(sum(balance_cents),0) FROM titles WHERE status IN ('pending','partial')),'partial_cents',(SELECT coalesce(sum(balance_cents),0) FROM titles WHERE status='partial'),'cancelled_cents',(SELECT coalesce(sum(amount_cents),0) FROM titles WHERE status='cancelled'),'confirmed_count',(SELECT count(*) FROM receipts WHERE status='confirmed'),'pending_count',(SELECT count(*) FROM titles WHERE status IN ('pending','partial')),'active_packages',(SELECT count(*) FROM public.care_packages WHERE account_id=aid AND lifecycle_status='ativo'))) INTO result;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.finance_query(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.finance_query(jsonb) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.finance_lookup(_kind text,_search text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE aid uuid:=public.current_account_id(); result jsonb; BEGIN IF NOT coalesce(public.can_manage_professional_finance(aid),false) THEN RAISE EXCEPTION 'Sem permissão financeira.'; END IF;
 IF _kind='patients' THEN SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') INTO result FROM(SELECT id,full_name AS name FROM public.patients WHERE account_id=aid AND full_name ILIKE '%'||left(_search,100)||'%' ORDER BY full_name LIMIT 20) s;
 ELSIF _kind='services' THEN SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') INTO result FROM(SELECT id,name FROM public.appointment_types WHERE account_id=aid AND is_active AND name ILIKE '%'||left(_search,100)||'%' ORDER BY name LIMIT 30) s;
 ELSIF _kind='packages' THEN SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') INTO result FROM(SELECT c.id,p.full_name||' · '||c.quantity||' sessões' AS name FROM public.care_packages c JOIN public.patients p ON p.id=c.patient_id WHERE c.account_id=aid AND p.full_name ILIKE '%'||left(_search,100)||'%' ORDER BY c.created_at DESC LIMIT 20) s;
 ELSE RAISE EXCEPTION 'Consulta inválida.'; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.finance_lookup(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.finance_lookup(text,text) TO authenticated,service_role;
